const spec = JSON.parse($input.first().binary.data.toString());
const scenes = spec.scenes;
const source = spec.source;

// Validate
if (!scenes || scenes.length < 2) throw new Error('Need at least 2 scenes');
if (!source) throw new Error('No source file in spec');

// Check source file exists
const fs = require('fs');
const path = require('path');
const root = 'D:\\Project-video';
const srcPath = path.resolve(root, source);
if (!fs.existsSync(srcPath)) throw new Error(`Source not found: ${srcPath}`);

return [{ json: { ...spec, _root: root, _srcPath: srcPath } }];

