={{ (() => {
  const spec = $json;
  const root = spec._root;
  const src = spec._srcPath;
  const scenes = spec.scenes;
  const layout = spec.layout || 'blur';

  // Build ffmpeg command for scene extraction + concat
  let inputs = '';
  let filters = '';
  const W = 1080, H = 1920, FPS = 30;

  scenes.forEach((sc, i) => {
    const parts = sc.start.split(':').map(Number);
    let startSec = 0;
    parts.forEach(p => { startSec = startSec * 60 + p; });
    const eParts = sc.end.split(':').map(Number);
    let endSec = 0;
    eParts.forEach(p => { endSec = endSec * 60 + p; });
    const dur = endSec - startSec;

    inputs += ` -ss ${startSec} -t ${dur} -i "${src}"`;

    if (layout === 'crop') {
      filters += `[${i}:v]scale=${W}:${H}:force_original_aspect_ratio=increase,crop=${W}:${H},fps=${FPS},setsar=1,format=yuv420p[v${i}];`;
    } else {
      filters += `[${i}:v]split[a${i}][b${i}];[a${i}]scale=${W}:${H}:force_original_aspect_ratio=increase,crop=${W}:${H},boxblur=30:5,eq=brightness=-0.12[bg${i}];[b${i}]scale=${W}:-2[fg${i}];[bg${i}][fg${i}]overlay=(W-w)/2:(H-h)/2,fps=${FPS},setsar=1,format=yuv420p[v${i}];`;
    }
    filters += `[${i}:a]aresample=48000,aformat=channel_layouts=stereo,atrim=0:${dur},asetpts=N/SR/TB[a${i}];`;
  });

  const n = scenes.length;
  const concatInputs = Array.from({length: n}, (_, i) => `[v${i}][a${i}]`).join('');
  filters += `${concatInputs}concat=n=${n}:v=1:a=1[v][a]`;

  const outPath = `${root}\\out\\${spec.id}_base.mp4`;
  return `ffmpeg -y -v error${inputs} -filter_complex "${filters}" -map "[v]" -map "[a]" -c:v libx264 -preset fast -crf 18 -c:a aac "${outPath}"`;
})() }}

