const fs = require('fs');
const path = require('path');
const spec = $json;
const root = spec._root;
const outMp4 = path.join(root, 'out', `${spec.id}.mp4`);
const outTxt = path.join(root, 'out', `${spec.id}.txt`);

const mp4Exists = fs.existsSync(outMp4);
const txtExists = fs.existsSync(outTxt);
const metadata = txtExists ? fs.readFileSync(outTxt, 'utf-8') : '';
const stats = mp4Exists ? fs.statSync(outMp4) : null;

return [{
  json: {
    id: spec.id,
    theme: spec.theme,
    film: spec.film,
    output_mp4: outMp4,
    output_txt: outTxt,
    file_size_mb: stats ? (stats.size / 1024 / 1024).toFixed(1) : 'N/A',
    metadata_preview: metadata.substring(0, 500),
    success: mp4Exists
  }
}];
